INSERT INTO products (id, name, price, numeric_price, old_price, category, image, short_description, description, suitable_for, safety_profile, pro_tip, attributes_json, key_actives_json) VALUES ('amla-reetha-shampoo', 'Herbalicious Amla Reetha (Organic Shampoo)', '₨ 1,000', 1000, '₨ 1,500', 'Organic Shampoo', '/Products/Amla Reetha Shampoo.webp', 'Promotes long & shiny hair, nourishes scalp.', 'Unlock the power of nature with Amla Reetha Shampoo. Strengthens hair follicles, stimulates growth, and imparts a lustrous shine. Suitable for all hair types.', 'All hair types, especially thinning and dull hair.', 'Paraben-Free, Sulfate-Free, No Synthetic Fragrances, Cruelty-Free.', 'For best results, leave the shampoo on your scalp for 2 minutes before rinsing to allow the Amla nutrients to penetrate deep into the roots.', '{"Weight": "50ml, 100ml", "pH Balanced": "Yes", "Sulfate Free": "Yes"}', '["Organic Amla Extract", "Natural Reetha (Soapnut)", "Aloe Vera Juice"]');
